// DISCOVER-1 (Rowan, 2026-11-25): the directory of every Ultrastable system. Core systems (the platform and every live tenant in
// this account) come from site/directory-data.js, generated by `python3 -m foundation discover --gen` from doctrine/tenant-repos.json,
// doctrine/topology.json and doctrine/stakeholders.json, so a new tenant is listed and cross-linked with no manual step. External
// systems register themselves with the seed's daily heartbeat (seed/worker/src/discover.js); the directory lists one only after it
// reads that site's own /.well-known/ultrastable.json, and drops it when the site opts out, says noindex, or fails three daily rechecks.
import CORE from "./directory-data.js";

const MANIFEST = "/.well-known/ultrastable.json";
const UA = { "user-agent": "ultrastable-directory/1 (+https://ultrastable.io/directory)" };
const clean = (s, n) => String(s == null ? "" : s).replace(/[\u0000-\u001f<>]/g, " ").trim().slice(0, n);
let made = null;
const table = (db) => made || (made = db.batch([
  db.prepare("CREATE TABLE IF NOT EXISTS directory_sites (origin TEXT PRIMARY KEY, name TEXT NOT NULL, repo TEXT, license TEXT, added TEXT NOT NULL, checked TEXT NOT NULL, fails INTEGER NOT NULL DEFAULT 0)"),
]).catch((e) => { made = null; throw e; }));

export function originOf(u) {
  try { const x = new URL(String(u)); if (x.protocol !== "https:" || x.username || x.port || /^(localhost|[\d.]+|\[.*\])$/.test(x.hostname) || !x.hostname.includes(".")) return null; return x.origin; } catch (e) { return null; }
}

// Read a site's own manifest and front page. Returns { ok, entry } or { ok: false, why }.
export async function inspect(origin, fetchFn) {
  let m;
  try {
    const r = await fetchFn(origin + MANIFEST, { headers: UA, redirect: "manual" });
    if (r.status !== 200) return { ok: false, why: "no manifest (" + r.status + ")" };
    m = await r.json();
  } catch (e) { return { ok: false, why: "manifest unreadable" }; }
  if (!m || m.ultrastable !== 1) return { ok: false, why: "not an Ultrastable manifest" };
  if (m.discoverable === false) return { ok: false, why: "opted out", optout: true };
  if (originOf(m.url) !== origin) return { ok: false, why: "manifest names a different URL" };
  try {
    const h = await fetchFn(origin + "/", { headers: UA, redirect: "follow" });
    const tag = (h.headers && h.headers.get && h.headers.get("x-robots-tag")) || "";
    const body = h.ok ? (await h.text()).slice(0, 20000) : "";
    if (/noindex/i.test(tag) || /<meta[^>]+name=["']?robots["']?[^>]+noindex/i.test(body)) return { ok: false, why: "noindex", optout: true };
    if (!h.ok) return { ok: false, why: "front page " + h.status };
  } catch (e) { return { ok: false, why: "front page unreachable" }; }
  const repo = /^https:\/\/github\.com\/[\w.-]+\/[\w.-]+$/.test(String(m.repo || "")) ? m.repo : null;
  return { ok: true, entry: { origin, name: clean(m.name, 80) || origin, repo, license: clean(m.license, 60) || null } };
}

export async function register(request, env, fetchFn) {
  if (!env || !env.DB) return Response.json({ ok: false, error: "directory_unavailable" }, { status: 503 });
  let body; try { body = await request.json(); } catch (e) { return Response.json({ ok: false, error: "bad_json" }, { status: 400 }); }
  const origin = originOf(body && body.url);
  if (!origin) return Response.json({ ok: false, error: "bad_url" }, { status: 400 });
  if (CORE.some((c) => originOf(c.url) === origin)) return Response.json({ ok: true, listed: "core" });
  await table(env.DB);
  const seen = await env.DB.prepare("SELECT checked FROM directory_sites WHERE origin = ?1").bind(origin).first();
  if (seen && Date.now() - Date.parse(seen.checked) < 6 * 3600e3) return Response.json({ ok: true, listed: true, fresh: true }, { status: 202 });
  const r = await inspect(origin, fetchFn);
  const at = new Date().toISOString();
  if (!r.ok) {
    if (r.optout) await env.DB.prepare("DELETE FROM directory_sites WHERE origin = ?1").bind(origin).run();
    return Response.json({ ok: false, error: "not_listed", why: r.why }, { status: 422 });
  }
  const e = r.entry;
  await env.DB.prepare("INSERT INTO directory_sites (origin, name, repo, license, added, checked, fails) VALUES (?1, ?2, ?3, ?4, ?5, ?5, 0) ON CONFLICT(origin) DO UPDATE SET name = ?2, repo = ?3, license = ?4, checked = ?5, fails = 0").bind(e.origin, e.name, e.repo, e.license, at).run();
  return Response.json({ ok: true, listed: true }, { status: 202 });
}

// Daily recheck from the site tick: a few of the oldest rows each pass; three failed days or an opt-out removes a row.
export async function recheck(env, fetchFn, now = new Date(), limit = 10) {
  if (!env || !env.DB) return { checked: 0 };
  await table(env.DB);
  const cut = new Date(now - 20 * 3600e3).toISOString();
  const rows = (await env.DB.prepare("SELECT origin, fails FROM directory_sites WHERE checked < ?1 ORDER BY checked LIMIT ?2").bind(cut, limit).all()).results || [];
  let dropped = 0;
  for (const row of rows) {
    const r = await inspect(row.origin, fetchFn), at = now.toISOString();
    if (r.ok) await env.DB.prepare("UPDATE directory_sites SET name = ?2, repo = ?3, license = ?4, checked = ?5, fails = 0 WHERE origin = ?1").bind(row.origin, r.entry.name, r.entry.repo, r.entry.license, at).run();
    else if (r.optout || row.fails + 1 >= 3) { await env.DB.prepare("DELETE FROM directory_sites WHERE origin = ?1").bind(row.origin).run(); dropped++; }
    else await env.DB.prepare("UPDATE directory_sites SET fails = fails + 1, checked = ?2 WHERE origin = ?1").bind(row.origin, at).run();
  }
  return { checked: rows.length, dropped };
}

export async function listing(env) {
  let ext = [];
  if (env && env.DB) {
    try { await table(env.DB); ext = ((await env.DB.prepare("SELECT origin, name, repo, license, added FROM directory_sites WHERE fails < 3 ORDER BY added LIMIT 500").all()).results || []).map((r) => ({ id: r.origin.replace(/^https:\/\//, ""), name: r.name, url: r.origin + "/", repo: r.repo, license: r.license, kind: "external" })); }
    catch (e) { console.error("directory read", e && e.message); }
  }
  return { core: CORE, external: ext, register: "POST https://ultrastable.io/api/directory/register {\"url\":\"https://your-site\"} (the site must serve " + MANIFEST + ")" };
}

export { CORE };
